package com.lamggm.rospocket;
import android.content.*;import android.content.res.*;import android.graphics.*;import android.util.DisplayMetrics;import android.view.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SquareCardCanvasTest {
 Bitmap draw(Context c,String mode,String wire,String name,int side)throws Exception{MetricCard card=new MetricCard(c);card.display(new DashboardLayout.Display(mode,"data",0,100,"V"));card.title(name);card.bind(0,1,wire,"std_msgs::msg::dds_::Float64_","Recebendo","42.5",true);card.sample(new JSONArray().put(new JSONObject().put("path","data").put("state","finite").put("value",42.5)),true);card.measure(View.MeasureSpec.makeMeasureSpec(side,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(side,View.MeasureSpec.EXACTLY));card.layout(0,0,side,side);Bitmap b=Bitmap.createBitmap(side,side,Bitmap.Config.ARGB_8888);card.draw(new Canvas(b));assertTrue(card.getContentDescription().toString().contains(wire));return b;}
 @Test public void nativeSquareCardsUseManualNamesAndKeepTheGaugeValueSeparateAt150Percent()throws Exception{
  Context c=RuntimeEnvironment.getApplication();Configuration old=new Configuration(c.getResources().getConfiguration());DisplayMetrics previous=new DisplayMetrics();previous.setTo(c.getResources().getDisplayMetrics());
  try{for(float font:new float[]{1f,1.5f})for(String theme:new String[]{"light","dark"}){Configuration conf=new Configuration(old);conf.fontScale=font;DisplayMetrics dm=new DisplayMetrics();dm.setTo(previous);dm.scaledDensity=dm.density*font;c.getResources().updateConfiguration(conf,dm);UiTheme.save(c,theme);int side=Math.round(120*dm.density*font),gap=Math.round(8*dm.density);Bitmap all=Bitmap.createBitmap(3*side+4*gap,side+2*gap,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(all);canvas.drawColor(UiTheme.color(c,0xff161d27));int i=0;for(String mode:new String[]{"number","gauge","bar"}){Bitmap b=draw(c,mode,"rt/namespace/a_very_long_original_topic","Velocidade",side);assertTrue("Manual name replaces the rendered topic, not its identity",b.sameAs(draw(c,mode,"rt/another_topic","Velocidade",side)));assertFalse("A different manual name must change real text pixels",b.sameAs(draw(c,mode,"rt/namespace/a_very_long_original_topic","Torque",side)));int obsoleteHeading=0;for(int y=Math.round(14*dm.density*font);y<Math.round(29*dm.density*font);y++)for(int x=Math.round(16*dm.density);x<Math.round(28*dm.density);x++)if(b.getPixel(x,y)==VisualButton.muted(c))obsoleteHeading++;assertEquals("Compact square header omits redundant slot label",0,obsoleteHeading);if(mode.equals("gauge")){int intruding=0,blue=0;for(int y=0;y<side;y++)for(int x=0;x<side;x++)if(b.getPixel(x,y)==0xff4688d4){blue++;if(y>=Math.round(87*dm.density*font))intruding++;}assertTrue(blue>0);assertEquals("Gauge ink must remain above numeric value band",0,intruding);}canvas.drawBitmap(b,gap+i*(side+gap),gap,null);i++;}String out=System.getenv("POCKET_SQUARE_PREVIEW_DIR");if(out!=null){java.nio.file.Files.createDirectories(java.nio.file.Paths.get(out));try(java.io.OutputStream s=java.nio.file.Files.newOutputStream(java.nio.file.Paths.get(out,"square-"+(int)(font*100)+"-"+theme+"-HOST-SYNTHETIC.png"))){all.compress(Bitmap.CompressFormat.PNG,100,s);}}}
  }finally{c.getResources().updateConfiguration(old,previous);}
 }
}
